 86	        for (Animal animal : neighboringAnimals) {
 87	            if (!(animal instanceof Predator)) {
 88	                animal.setDead();
 89	                foodLevel += animal.getNutritionalValue();
 90	                return animal.getLocation();
 91	            }
 92	        }
 93	        // No food found
 94	        return null;
 95	    }
