 97	    /**
 98	     * Check if predator if under attack from a horde of another species of predator. If a horde is attacking it and the horde's strength
 99	     * is greater than the predator's one, the horde members eat it.
100	     *
101	     * @param  neighboringAnimals (ArrayList<Animal>) A list of neighboring animals.
102	     */
103	    private void checkForAttack(List<Animal> neighboringAnimals)
104	    {
105	        HashMap<String, ArrayList<Predator>> hordesBySpecies = new HashMap<>();
106	
107	        for (Animal animal : neighboringAnimals) {
108	            if (animal instanceof Predator) {
109	                Predator predator = (Predator) animal;
110	                if (!predator.getName().equals(getName())) {
111	                    ArrayList<Predator> hordeMembers = hordesBySpecies.get(predator.getName());
112	                    if (hordeMembers == null) {
113	                        hordeMembers = new ArrayList<>();
114	                        hordesBySpecies.put(predator.getName(), hordeMembers);
115	                    }
116	                    hordeMembers.add(predator);
117	                }
118	            }
119	        }
120	
121	        for (ArrayList<Predator> hordeMembers : hordesBySpecies.values()) {
122	            if (calculateHordeStrength(hordeMembers) > strength) {
123	                attackedByHorde(hordeMembers);
124	                return;
125	            }
126	        }
127	    }
128	
129	    /**
130	     * Calculate the combined strength of a horde.
131	     *
132	     * @param hordeMembers the predators in the horde.
133	     * @return the total strength.
134	     */
135	    private int calculateHordeStrength(List<Predator> hordeMembers)
136	    {
137	        int totalStrength = 0;
138	        for (Predator predator : hordeMembers) {
139	            totalStrength += predator.getStrength();
140	        }
141	        return totalStrength;
142	    }
143	
144	    /**
145	     * Animal is under attack by a horde whose strength is greater than its own. It is eaten by the horde and dies. Its nutritional value
146	     * is therefore shared
147	     *
148	     * @param hordeMembers (ArrayList<Predator>) List of the predators constituting the horde.
149	     */
150	    private void attackedByHorde(ArrayList<Predator> hordeMembers)
151	    {
152	        // Sharing predator's nutritional value amongst the various horde members.
153	        int foodLevelAddedToEachHordeMember = this.getNutritionalValue() / hordeMembers.size();
154	        for (Predator predator : hordeMembers) {
155	            predator.incrementFoodLevel(foodLevelAddedToEachHordeMember);
156	        }
157	        this.setDead();
158	    }
