160	    /**
161	     * Creates the appropriate number of predators of the same species due to reproduction. These new predators of course share the same
162	     * features as their "parent" except the sex which is randomized, their age and foodLevel are not randomized.
163	     *
164	     * @param newOfThisKind (List<Species>) The list of species to which newborns must be added.
165	     */
166	    protected void reproduce(List<Species> newOfThisKind)
167	    {
168	        Field field = getField();
169	        if (field != null)
170	        {
171	            List<Location> free = field.getFreeAdjacentLocations(getLocation());
172	            int births = numberOfBirths();
173	            for(int b = 0; b < births && free.size() > 0; b++) {
174	                Location loc = free.remove(0);
175	                Predator young = new Predator(strength, field, loc, getName(), getMaximumTemperature(), getMinimumTemperature(), getNutritionalValue(), getReproductionProbability(), getMaxAge(), getBreedingAge(), getMaxLitterSize(),false, getHibernates(), getIsNocturnal());
176	                newOfThisKind.add(young);
177	            }
178	        }
179	    }
