182	     * Returns the predator's strength, public so that other predators can consult the strength of a pontential horde this predator could
183	     * be a part of.
184	     *
185	     * @return (int) the predator's strength.
186	     */
187	    public int getStrength() {
188	        return strength;
189	    }
