 59	    public Animal(Field field, Location location, String name, int maximumTemperature, int minimumTemperature, int nutritionalValue, double reproductionProbability, int maxAge, int breedingAge, int maxLitterSize, boolean randomAge, boolean hibernates, boolean isNocturnal)
 60	    {
 61	        super(field, location, name, maximumTemperature, minimumTemperature, nutritionalValue, reproductionProbability);
 62	
 63	        this.breedingAge = breedingAge;
 64	        this.maxAge = maxAge;
