 81	    /**
 82	     * Imitate an animal's step by doing the following:
 83	     * 1) increment the animal's age if a year has passed.
 84	     * 2) if the animal is alive, then:
 85	     *      i) check if the animal should hibernate.
 86	     *      ii) if the animal is in hibernation, then:
 87	     *          a) if it passed STAY_STEPS steps without moving, then move and increment hunger.
 88	     *          b) increment hiberSteps.
 89	     *      iii) if the animal can't withstand the current temperature, then it dies.
 90	     *      iv) if the animal is not in hibernation, then:
 91	     *          a) if it is night and the animal is nocturnal, then move.
 92	     *          b) if it is day, then all animals move and increment hunger.
 93	     *
 94	     * @param newSpecies (List<Species>) A list to receive newly born animals.
 95	     * @param isNight (boolean) true if it is night in the simulation
 96	     * @param temperature (int) the current temperature of the simulation
 97	     * @param yearPassed true if a year has passed in the simulation
 98	     */
 99	    public void act(List<Species> newSpecies, boolean isNight, int temperature, boolean yearPassed)
100	    {
101	        if (yearPassed) {
102	            incrementAge();
103	        }
104	
105	        if (!isAlive()) {
106	            return;
107	        }
108	
109	        checkHibernation(temperature);
110	
111	        if (inHibernation) {
112	            handleHibernatingStep(newSpecies);
113	        }
114	        else if (!survivesTemperature(temperature)) {
115	            setDead();
116	        }
117	        else {
118	            handleAwakeStep(newSpecies, isNight);
119	        }
120	    }
