122	    /**
123	     * Handle a step while the animal is hibernating.
124	     *
125	     * @param newSpecies a list to receive newborn species.
126	     */
127	    private void handleHibernatingStep(List<Species> newSpecies)
128	    {
129	        if (hiberSteps % STAY_STEPS == 0) {
130	            makeMove(newSpecies);
131	            incrementHunger();
132	        }
133	        incrementHiberSteps();
134	    }
135	
136	    /**
137	     * Handle a step while the animal is awake.
138	     *
139	     * @param newSpecies a list to receive newborn species.
140	     * @param isNight true if it is currently night.
141	     */
142	    private void handleAwakeStep(List<Species> newSpecies, boolean isNight)
143	    {
144	        if (shouldMoveThisStep(isNight)) {
145	            makeMove(newSpecies);
146	        }
147	        if (!isNight) {
148	            incrementHunger();
149	        }
150	    }
