152	    /**
153	     * @param isNight true if it is currently night.
154	     * @return true if the animal should move on this step.
155	     */
156	    private boolean shouldMoveThisStep(boolean isNight)
157	    {
158	        return !isNight || isNocturnal;
159	    }
