161	    /**
162	     * An animal's movement. It first tries to reproduce, then to eat if a plant is in one of the neighboring cells and finally to move
163	     * if an adjacent cell is available. If no adjacent cell is available, it dies of overcrowding.
164	     *
165	     * @param newSpecies (List<Species>) A list to receive newly born animals.
166	     */
167	    protected void makeMove(List<Species> newSpecies)
168	    {
169	        List<Animal> neighboringAnimalsList = getNeighboringAnimalsList();
170	
171	        if (canReproduce(neighboringAnimalsList)) {
172	            reproduce(newSpecies);
173	        }
174	
175	        // Eats if it is possible
176	        if (isNotFull()) {
177	            findFoodAndEat();
178	        }
179	
180	        moveToFreeAdjacentLocationOrDie();
181	    }
