183	    /**
184	     * Returns a list of animals located in neighboring cells.
185	     *
186	     * @return (ArrayList) list of neighboring animals
187	     */
188	    protected List<Animal> getNeighboringAnimalsList()
189	    {
190	        Field field = getField();
191	        ArrayList<Animal> neighboringAnimals = new ArrayList<>();
192	        for (Location where : field.adjacentLocations(getLocation())) {
193	            Object species = field.getObjectAt(where);
194	
195	            if (species instanceof Animal) {
196	                Animal neighboringAnimal = (Animal) species;
197	                if (neighboringAnimal.isAlive()) {
198	                    neighboringAnimals.add(neighboringAnimal);
199	                }
200	            }
201	        }
202	        return neighboringAnimals;
203	    }
