244	     * Look for plants adjacent to the current location.
245	     * Only the first plant is eaten.
246	     */
247	    private void findFoodAndEat()
248	    {
249	        Field field = getField();
250	        for (Location where : field.adjacentLocations(getLocation())) {
251	            Object species = field.getObjectAt(where);
252	            if(species instanceof Plant) {
253	                Plant plantSquare = (Plant) species;
254	                if(plantSquare.isAlive()) {
255	                    plantSquare.isEaten();
