263	    /**
264	     * If the animal is a female, check if a male of the same species is in one of the neighboring cells. If it is the case, animal is able to reproduce
265	     *  and should go to the cel where the male is.
266	     *  Note: The task of reproducing is handled only by females so that the same reproduction can not happen twice in the same simulator step.
267	     *
268	     * @param neighboringAnimalsList a list of the animals located in neighboring cells.
269	     * @return true if the animal can reproduce.
270	     */
271	    protected boolean canReproduce(List<Animal> neighboringAnimalsList)
272	    {
273	        // task to reproduce is handed to women only so that the same reproduction does not happen twice
274	        if (this.isFemale)
275	        {
276	            for (Animal neighbor : neighboringAnimalsList) {
277	                if (!neighbor.isFemale && neighbor.getName().equals(this.getName())) {
278	                    // The neighbor is a male of the same species
279	                    return true;
280	                }
281	            }
282	        }
283	        return false;
284	    }
